      ],
      "paragraph_starts": [
        {"text": "illégitime, autant sa réalisation minutieuse et nuancée offre l'occasion de redécouvrir", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Au lieu de renouveler la lecture d'un grand auteur, Jean-François Courtine a", "continues_from_previous": false, "continues_to_next": false}
      ],
