        {"marker": "180", "text_start": "Voir ibid., § 6, p. 73 sq."},
        {"marker": "181", "text_start": "Allusion à la thèse de Jean-Luc MARION, Sur la théologie blanche de Descartes, Paris, PUF, 1981."},
        {"marker": "182", "text_start": "Voir J.-L. MARION, Sur le prisme..., op. cit., § 10 et le schéma p. 129."},
        {"marker": "183", "text_start": "Ibid., p. 128."}
